import math


def haircut(best_sharpe, n_trials, years):
    return best_sharpe - math.sqrt(2 * math.log(n_trials)) / years

import math


def haircut(best_sharpe, n_trials, years):
    return best_sharpe - math.sqrt(2 * math.log10(n_trials)) / math.sqrt(years)

import math


def haircut(best_sharpe, n_trials, years):
    return best_sharpe - math.sqrt(2 * math.log(n_trials + 1)) / math.sqrt(years)
